begin;
create extension if not exists pgcrypto;
create table if not exists public.angelcare_marketplace_locales(id uuid primary key default gen_random_uuid(),code text not null unique check(code in('fr','en','ar')),name text not null,native_name text not null,direction text not null check(direction in('ltr','rtl')),is_source boolean not null default false,enabled boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_localization_source_registries(id uuid primary key default gen_random_uuid(),source_key text not null unique,adapter_type text not null,source_scope jsonb not null default '{}'::jsonb,required boolean not null default true,enabled boolean not null default true,last_successful_scan_at timestamptz,last_error text,owner_id uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_localization_scan_runs(id uuid primary key default gen_random_uuid(),scan_type text not null,status text not null check(status in('queued','running','completed','completed_with_warnings','failed','cancelled')),requested_by uuid,trigger_type text not null,request_payload jsonb not null default '{}'::jsonb,source_snapshot text,started_at timestamptz,completed_at timestamptz,scanned_files integer not null default 0,candidates_found integer not null default 0,new_candidates integer not null default 0,changed_candidates integer not null default 0,removed_candidates integer not null default 0,failed_sources integer not null default 0,adapter_counts jsonb not null default '{}'::jsonb,failure_details jsonb not null default '[]'::jsonb,coverage_percentage numeric(5,2),freshness_percentage numeric(5,2),created_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_translation_candidates(id uuid primary key default gen_random_uuid(),translation_key text not null unique,source_locale text not null default 'fr' check(source_locale='fr'),source_text_fr text not null,source_hash text not null,source_version integer not null default 1,source_type text not null,source_adapter text not null,source_path text,source_line integer,source_column integer,route text,component text,database_schema text,database_table text,database_row_id text,database_field text,template_id text,domain text not null,workflow text,audience text,territory_id uuid,tenant_id uuid,content_type text not null,sensitivity text not null default 'ordinary',context_description text,developer_note text,translator_note text,variables jsonb not null default '[]'::jsonb,character_limit integer,supports_html boolean not null default false,directionality_risk boolean not null default false,classification text not null default 'needs_human_review',classification_confidence numeric(5,4),discovery_evidence jsonb not null default '{}'::jsonb,freshness_state text not null default 'new',first_discovered_at timestamptz not null default now(),last_seen_at timestamptz not null default now(),last_changed_at timestamptz not null default now(),last_scan_id uuid references public.angelcare_marketplace_localization_scan_runs(id),owner_id uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_translation_versions(id uuid primary key default gen_random_uuid(),candidate_id uuid not null references public.angelcare_marketplace_translation_candidates(id) on delete cascade,source_version integer not null,source_text_fr text not null,source_hash text not null,changed_by uuid,change_reason text,created_at timestamptz not null default now(),unique(candidate_id,source_version));
create table if not exists public.angelcare_marketplace_translations(id uuid primary key default gen_random_uuid(),candidate_id uuid not null references public.angelcare_marketplace_translation_candidates(id) on delete cascade,target_locale text not null check(target_locale in('en','ar')),translation_text text not null default '',translation_hash text,status text not null default 'draft',freshness_state text not null default 'missing',source_hash_at_translation text,version integer not null default 1,translator_id uuid,reviewer_id uuid,approved_by uuid,published_by uuid,reviewer_note text,published_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(candidate_id,target_locale));
create table if not exists public.angelcare_marketplace_translation_reviews(id uuid primary key default gen_random_uuid(),translation_id uuid not null references public.angelcare_marketplace_translations(id) on delete cascade,decision text not null,reviewer_id uuid not null,comments text,quality_checks jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_glossary_terms(id uuid primary key default gen_random_uuid(),term_key text not null unique,source_fr text not null,approved_en text,approved_ar text,brand_locked boolean not null default false,translation_allowed boolean not null default true,usage_guidance text,prohibited_variants jsonb not null default '[]'::jsonb,status text not null default 'approved',owner_id uuid,reviewer_id uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_translation_memory(id uuid primary key default gen_random_uuid(),source_text_fr text not null,source_hash text not null,target_locale text not null,target_text text not null,domain text,context text,territory_id uuid,quality_score numeric(5,2),approved boolean not null default false,approved_by uuid,usage_count integer not null default 0,last_used_at timestamptz,created_at timestamptz not null default now(),unique(source_hash,target_locale,target_text));
create table if not exists public.angelcare_marketplace_translation_feedback(id uuid primary key default gen_random_uuid(),candidate_id uuid references public.angelcare_marketplace_translation_candidates(id),translation_id uuid references public.angelcare_marketplace_translations(id),feedback_type text not null,previous_value jsonb,new_value jsonb,reviewer_id uuid,applied_to_rules boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_translation_exports(id uuid primary key default gen_random_uuid(),scan_id uuid references public.angelcare_marketplace_localization_scan_runs(id),target_locale text not null,filters jsonb not null default '{}'::jsonb,row_count integer not null default 0,checksum text,storage_path text,status text not null default 'generated',exported_by uuid,created_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_translation_imports(id uuid primary key default gen_random_uuid(),export_id uuid references public.angelcare_marketplace_translation_exports(id),target_locale text not null,file_name text not null,file_checksum text,status text not null default 'uploaded',row_count integer not null default 0,valid_rows integer not null default 0,invalid_rows integer not null default 0,conflict_rows integer not null default 0,dry_run_result jsonb,uploaded_by uuid,approved_by uuid,applied_by uuid,applied_at timestamptz,rolled_back_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_translation_import_rows(id uuid primary key default gen_random_uuid(),import_id uuid not null references public.angelcare_marketplace_translation_imports(id) on delete cascade,row_number integer not null,candidate_id uuid references public.angelcare_marketplace_translation_candidates(id),translation_key text not null,source_hash text not null,target_locale text not null,proposed_translation text,row_status text not null default 'pending',errors jsonb not null default '[]'::jsonb,warnings jsonb not null default '[]'::jsonb,applied_translation_id uuid,created_at timestamptz not null default now(),unique(import_id,row_number));
create table if not exists public.angelcare_marketplace_translation_apply_changes(id uuid primary key default gen_random_uuid(),import_id uuid not null references public.angelcare_marketplace_translation_imports(id),translation_id uuid references public.angelcare_marketplace_translations(id),before_value jsonb,after_value jsonb,rollback_value jsonb,applied_by uuid,rolled_back_by uuid,created_at timestamptz not null default now(),rolled_back_at timestamptz);
create table if not exists public.angelcare_marketplace_seo_metadata(id uuid primary key default gen_random_uuid(),route text not null,territory_id uuid,locale text not null check(locale in('fr','en','ar')),title text,description text,canonical_url text,open_graph_title text,open_graph_description text,indexing_status text not null default 'draft',status text not null default 'draft',owner_id uuid,reviewer_id uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_localized_slugs(id uuid primary key default gen_random_uuid(),route_key text not null,territory_id uuid,locale text not null,slug text not null,status text not null default 'draft',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(route_key,territory_id,locale));
create table if not exists public.angelcare_marketplace_locale_readiness_snapshots(id uuid primary key default gen_random_uuid(),territory_id uuid,route text,scan_id uuid references public.angelcare_marketplace_localization_scan_runs(id),required_candidates integer not null default 0,current_fr integer not null default 0,current_en integer not null default 0,current_ar integer not null default 0,sensitive_blockers integer not null default 0,failed_sources integer not null default 0,readiness_score numeric(5,2),is_truthful_complete boolean not null default false,calculated_at timestamptz not null default now());
create index if not exists idx_ac_mp_translation_candidates_scan on public.angelcare_marketplace_translation_candidates(last_scan_id); create index if not exists idx_ac_mp_translation_candidates_freshness on public.angelcare_marketplace_translation_candidates(freshness_state); create index if not exists idx_ac_mp_translation_candidates_route on public.angelcare_marketplace_translation_candidates(route); create index if not exists idx_ac_mp_translations_status on public.angelcare_marketplace_translations(status,freshness_state); create index if not exists idx_ac_mp_import_rows_status on public.angelcare_marketplace_translation_import_rows(import_id,row_status);
create or replace view public.angelcare_marketplace_translation_inventory_v as select c.id candidate_id,c.translation_key,c.source_text_fr,c.source_hash,c.source_version,c.source_type,c.source_adapter,c.source_path,c.source_line,c.route,c.domain,c.workflow,c.territory_id,c.tenant_id,c.content_type,c.sensitivity,c.context_description,c.variables,c.character_limit,c.freshness_state,c.last_changed_at,max(t.translation_text) filter(where t.target_locale='en') en_translation,max(t.status) filter(where t.target_locale='en') en_status,max(t.translation_text) filter(where t.target_locale='ar') ar_translation,max(t.status) filter(where t.target_locale='ar') ar_status,coalesce(max(t.status),'translation_required') translation_status from public.angelcare_marketplace_translation_candidates c left join public.angelcare_marketplace_translations t on t.candidate_id=c.id group by c.id;
create or replace function public.angelcare_marketplace_mark_translations_stale() returns trigger language plpgsql security definer set search_path=public as $$ begin if old.source_hash is distinct from new.source_hash then new.source_version=old.source_version+1; new.last_changed_at=now(); new.freshness_state='changed'; insert into public.angelcare_marketplace_translation_versions(candidate_id,source_version,source_text_fr,source_hash,created_at) values(old.id,old.source_version,old.source_text_fr,old.source_hash,now()) on conflict do nothing; update public.angelcare_marketplace_translations set status='stale',freshness_state='translation_stale',updated_at=now() where candidate_id=old.id and status='published'; end if; return new; end $$;
drop trigger if exists trg_ac_mp_translation_source_change on public.angelcare_marketplace_translation_candidates; create trigger trg_ac_mp_translation_source_change before update on public.angelcare_marketplace_translation_candidates for each row execute function public.angelcare_marketplace_mark_translations_stale();
insert into public.angelcare_marketplace_locales(code,name,native_name,direction,is_source) values('fr','Français','Français','ltr',true),('en','Anglais','English','ltr',false),('ar','Arabe','العربية','rtl',false) on conflict(code) do update set name=excluded.name,native_name=excluded.native_name,direction=excluded.direction,is_source=excluded.is_source,updated_at=now();
insert into public.angelcare_marketplace_localization_source_registries(source_key,adapter_type,source_scope,required) values('marketplace-source-ast','source_ast','{"root":"angelcare-marketplace"}',true),('marketplace-backend-api','backend_api','{"roots":["angelcare-marketplace","app/api/angelcare-marketplace"]}',true),('marketplace-db-registry','database_registry','{"allowlistOnly":true}',true),('marketplace-runtime-render','runtime_render','{"routePrefix":"/angelcare-marketplace"}',true),('marketplace-communications','communication_template','{"registeredTemplatesOnly":true}',true),('marketplace-seo','seo_metadata','{"routePrefix":"/angelcare-marketplace"}',true),('marketplace-content','content_file','{"root":"angelcare-marketplace"}',true) on conflict(source_key) do nothing;
insert into public.angelcare_marketplace_glossary_terms(term_key,source_fr,approved_en,approved_ar,brand_locked,translation_allowed,status) values('angelcare','ANGELCARE','ANGELCARE','ANGELCARE',true,false,'approved'),('partner-os','Partner OS','Partner OS','Partner OS',true,false,'approved'),('parenttrust','ParentTrust','ParentTrust','ParentTrust',true,false,'approved'),('quality-check-360','Quality Check 360','Quality Check 360','Quality Check 360',true,false,'approved'),('kids-specialist','AngelCare Kids Specialist','AngelCare Kids Specialist','أخصائي أطفال AngelCare',false,true,'approved'),('academy','Academy','Academy','الأكاديمية',false,true,'approved'),('territory-os','Territory OS','Territory OS','نظام المناطق',false,true,'approved'),('master-backoffice','Master Backoffice','Master Backoffice','الإدارة المركزية',false,true,'approved') on conflict(term_key) do nothing;
update public.angelcare_marketplace_modules set status='enabled',enabled=true,route_prefix='/angelcare-marketplace/admin/localization',required_permissions=array[
  'marketplace.localization.access'
]::text[],health_status='attention_required',version=version+1,updated_at=now() where module_key in('localization','localization-seo','mega-zip-03');
insert into public.angelcare_marketplace_feature_flags(flag_key,name,description,enabled,scope_type,status,owner_id,reason) values('marketplace.localization-intelligence.enabled','Localization Intelligence OS','Scanner continu, fulfillment CSV, French source authority et RTL.',true,'global','active',null,'Activation Mega ZIP 03') on conflict(flag_key) do update set enabled=true,status='active',description=excluded.description,updated_at=now();
do $$ declare t text; begin foreach t in array array['angelcare_marketplace_locales','angelcare_marketplace_localization_source_registries','angelcare_marketplace_localization_scan_runs','angelcare_marketplace_translation_candidates','angelcare_marketplace_translation_versions','angelcare_marketplace_translations','angelcare_marketplace_translation_reviews','angelcare_marketplace_glossary_terms','angelcare_marketplace_translation_memory','angelcare_marketplace_translation_feedback','angelcare_marketplace_translation_exports','angelcare_marketplace_translation_imports','angelcare_marketplace_translation_import_rows','angelcare_marketplace_translation_apply_changes','angelcare_marketplace_seo_metadata','angelcare_marketplace_localized_slugs','angelcare_marketplace_locale_readiness_snapshots'] loop execute format('alter table public.%I enable row level security',t); execute format('revoke all on table public.%I from anon, authenticated',t); execute format('grant all on table public.%I to service_role',t); end loop; end $$;
revoke all on public.angelcare_marketplace_translation_inventory_v from anon,authenticated; grant select on public.angelcare_marketplace_translation_inventory_v to service_role;
commit;
